-- ════════════════════════════════════════════════════════════════════════
-- Despesas do grupo de WhatsApp "Compravnates outubro" (03 a 13/10/2026)
-- 51 despesas, R$ 249,793.52. Lidas de cada comprovante (valor, data e favorecido
-- do banco; a legenda do grupo vira o tipo). 52 fotos: a 00000159 é cópia da 00000158.
--
-- Não duplica: pula o comprovante quando já existe despesa com a mesma data e o
-- mesmo valor (lançada à mão ou pelo Atalho do iPhone). A consulta no fim mostra
-- quais ficaram de fora por isso.
-- Cole tudo no SQL Editor do Supabase e clique em Run. Pode rodar de novo.
-- Para desfazer: delete from public.despesas where importado = 'WHATSAPP-OUT2026';
-- ════════════════════════════════════════════════════════════════════════

begin;

alter table public.despesas add column if not exists importado text;


commit;

-- Conferência: comprovantes que NÃO entraram porque já havia despesa igual (mesma data e valor).
select x.data, x.valor, x.tipo, d.descricao as ja_lancada_como, d.importado as origem
from (values ('2026-10-03'::date, 70.00::numeric, 'Reparo 1620'), ('2026-10-03'::date, 86.00::numeric, 'Mangueira imbutidor'), ('2026-10-04'::date, 9727.00::numeric, 'Compra laranja Ailton'), ('2026-10-04'::date, 500.00::numeric, 'Quinzena gordinho'), ('2026-10-05'::date, 200.00::numeric, 'PTV'), ('2026-10-05'::date, 7062.00::numeric, 'Laranja sábado Elizeu'), ('2026-10-05'::date, 29940.00::numeric, 'Cera laranja Tota'), ('2026-10-05'::date, 5154.18::numeric, 'Arrendamento Triunfo'), ('2026-10-06'::date, 17213.63::numeric, 'Pix cartão de crédito (Itaú)'), ('2026-10-06'::date, 18994.14::numeric, 'Diesel Caioba (Carvalho + milho)'), ('2026-10-06'::date, 300.00::numeric, 'Pesos balança'), ('2026-10-07'::date, 75.00::numeric, 'Reparo mangueira'), ('2026-10-07'::date, 4664.00::numeric, 'Compra laranja Elizeu'), ('2026-10-07'::date, 975.85::numeric, 'Cobertura pneu'), ('2026-10-07'::date, 1151.05::numeric, 'Itapneus'), ('2026-10-07'::date, 464.61::numeric, 'Itapneus'), ('2026-10-07'::date, 3726.00::numeric, 'Boleto poer (Pix para Lucas)'), ('2026-10-08'::date, 4000.00::numeric, 'Garagem Jandaíra'), ('2026-10-08'::date, 28.00::numeric, 'Almoço'), ('2026-10-08'::date, 2035.00::numeric, 'Transferência para a conta do BNB'), ('2026-10-09'::date, 1600.52::numeric, 'Empréstimo Mercado Pago'), ('2026-10-09'::date, 35.00::numeric, 'Almoço Jhun'), ('2026-10-09'::date, 200.00::numeric, 'Bling'), ('2026-10-09'::date, 34740.00::numeric, 'Arrendamento milho Gameleira'), ('2026-10-09'::date, 36763.20::numeric, 'Arrendamento Juerana'), ('2026-10-09'::date, 466.68::numeric, 'Innovar'), ('2026-10-09'::date, 30.00::numeric, 'Janta Jhun'), ('2026-10-10'::date, 250.00::numeric, 'Cuíca 1620'), ('2026-10-10'::date, 600.00::numeric, 'Ensaque silagem Batinga'), ('2026-10-10'::date, 130.00::numeric, 'Mão de obra 1620'), ('2026-10-10'::date, 750.00::numeric, 'Semana Jhun'), ('2026-10-10'::date, 13658.00::numeric, 'Turma de colheita'), ('2026-10-10'::date, 2811.20::numeric, 'Turma de colheita'), ('2026-10-10'::date, 150.00::numeric, 'Carregador'), ('2026-10-10'::date, 600.00::numeric, 'Sivaldo'), ('2026-10-10'::date, 480.00::numeric, 'Horas retro'), ('2026-10-10'::date, 1200.00::numeric, 'Diárias Nardo'), ('2026-10-10'::date, 180.00::numeric, 'Horas Cauan'), ('2026-10-10'::date, 200.00::numeric, 'Pesos balança'), ('2026-10-12'::date, 4532.88::numeric, 'Mercado Pago'), ('2026-10-12'::date, 6172.00::numeric, 'Compra laranja'), ('2026-10-12'::date, 750.00::numeric, 'Panha laranja'), ('2026-10-12'::date, 50.00::numeric, 'Carrego lima'), ('2026-10-13'::date, 12933.57::numeric, 'Pix cartão de crédito BB'), ('2026-10-13'::date, 400.00::numeric, 'PTVs'), ('2026-10-13'::date, 1200.00::numeric, 'CFO'), ('2026-10-13'::date, 2000.00::numeric, 'Contabilidade'), ('2026-10-13'::date, 3707.36::numeric, 'Diesel Caioba'), ('2026-10-13'::date, 16584.15::numeric, '3ª parcela imposto 2º trimestre'), ('2026-10-13'::date, 2.50::numeric, 'Parafusos'), ('2026-10-13'::date, 250.00::numeric, 'M.O. 1620')) as x(data, valor, tipo)
join public.despesas d on d.data = x.data and round(d.valor::numeric, 2) = x.valor and coalesce(d.importado, '') <> 'WHATSAPP-OUT2026'
order by 1;

